    "slug": "2025-ai-advances-from-data-collection-to-data-in-action",
    "year": "2025",
    "category": "enterprise-fintech",
    "title": {
      "en": "AI Advances From Data Collection to Data-in-Action",
      "zh": "AI 從資料蒐集邁向資料行動化"
    },
    "author": "Seema Amble",
